package ec.edu.monster.modelo;
public class Resultado { private boolean exito; private String mensaje; private double saldo; public Resultado(){} private Resultado(boolean e,String m,double s){exito=e;mensaje=m;saldo=s;} public static Resultado ok(String m,double s){return new Resultado(true,m,s);} public static Resultado error(String m){return new Resultado(false,m,0);} public boolean isExito(){return exito;} public void setExito(boolean v){exito=v;} public String getMensaje(){return mensaje;} public void setMensaje(String v){mensaje=v;} public double getSaldo(){return saldo;} public void setSaldo(double v){saldo=v;} }
